(function() {
  window.CardSpoke.Plugin.register('pomodoro-desk', {
    manifest: {
      name: 'Pomodoro Desk',
      version: '1.0.0',
      author: 'CardSpoke Community',
      description: 'Productivity workspace with Pomodoro timer and session tracking',
      layer: 'app',
      permissions: ['ui-override', 'storage']
    },
    setup: async function(ctx) {
      var self = this;
      document.body.classList.add('pomodoro-desk-active');
      var WORK_DURATION = 25 * 60;
      var BREAK_DURATION = 5 * 60;
      var LONG_BREAK_DURATION = 15 * 60;
      var state = {
        timeLeft: WORK_DURATION,
        isRunning: false,
        isBreak: false,
        sessionsCompleted: 0,
        todayMinutes: 0,
        history: [],
        interval: null,
        minimized: false
      };
      var savedSessions = await ctx.api.storage.get('sessions');
      if (savedSessions && Array.isArray(savedSessions)) {
        var today = new Date().toISOString().slice(0, 10);
        state.history = savedSessions.filter(function(s) { return s.date === today; });
        state.sessionsCompleted = state.history.length;
        state.todayMinutes = state.history.reduce(function(sum, s) { return sum + (s.minutes || 0); }, 0);
      }
      var panel = document.createElement('div');
      panel.className = 'pomodoro-panel';
      panel.id = 'pomodoro-panel';
      panel.innerHTML = '<div class="pomodoro-panel-header"><span>Pomodoro Desk</span><button class="pomodoro-panel-minimize">_</button></div>' +
        '<div class="pomodoro-timer-display"><div class="pomodoro-time">25:00</div><div class="pomodoro-status">Ready to focus</div></div>' +
        '<div class="pomodoro-controls">' +
        '<button class="pomodoro-btn pomodoro-btn-start">Start</button>' +
        '<button class="pomodoro-btn pomodoro-btn-reset">Reset</button></div>' +
        '<div class="pomodoro-today-stats">' +
        '<div class="pomodoro-stat"><div class="pomodoro-stat-value" id="pomo-sessions">0</div>sessions</div>' +
        '<div class="pomodoro-stat"><div class="pomodoro-stat-value" id="pomo-minutes">0</div>minutes</div>' +
        '<div class="pomodoro-stat"><div class="pomodoro-stat-value" id="pomo-cards">0</div>cards</div></div>' +
        '<div class="pomodoro-sessions"><div class="pomodoro-sessions-title">Session History</div><div id="pomo-history"></div></div>';
      document.body.appendChild(panel);
      self._panel = panel;
      var minBtn = document.createElement('button');
      minBtn.className = 'pomodoro-minimized';
      minBtn.id = 'pomodoro-minimized-btn';
      document.body.appendChild(minBtn);
      self._minBtn = minBtn;
      var timeEl = panel.querySelector('.pomodoro-time');
      var statusEl = panel.querySelector('.pomodoro-status');
      var startBtn = panel.querySelector('.pomodoro-btn-start');
      var resetBtn = panel.querySelector('.pomodoro-btn-reset');
      var minimizeBtn = panel.querySelector('.pomodoro-panel-minimize');
      var sessionsEl = panel.querySelector('#pomo-sessions');
      var minutesEl = panel.querySelector('#pomo-minutes');
      var cardsEl = panel.querySelector('#pomo-cards');
      var historyEl = panel.querySelector('#pomo-history');
      function formatTime(seconds) {
        var m = Math.floor(seconds / 60);
        var s = seconds % 60;
        return (m < 10 ? '0' : '') + m + ':' + (s < 10 ? '0' : '') + s;
      }
      function updateDisplay() {
        timeEl.textContent = formatTime(state.timeLeft);
        timeEl.className = 'pomodoro-time' + (state.isBreak ? ' break-time' : '');
        statusEl.textContent = state.isRunning ? (state.isBreak ? 'Break time' : 'Focusing...') : (state.isBreak ? 'Break paused' : 'Ready to focus');
        startBtn.textContent = state.isRunning ? 'Pause' : 'Start';
        startBtn.className = 'pomodoro-btn ' + (state.isRunning ? 'pomodoro-btn-pause' : 'pomodoro-btn-start');
        sessionsEl.textContent = state.sessionsCompleted;
        minutesEl.textContent = state.todayMinutes;
        cardsEl.textContent = ctx.api.data.listCards().length;
        minBtn.textContent = formatTime(state.timeLeft) + (state.isRunning ? (state.isBreak ? ' break' : ' focus') : '');
      }
      function renderHistory() {
        if (state.history.length === 0) {
          historyEl.innerHTML = '<div style="color:#aaa;font-size:11px;">No sessions yet today</div>';
          return;
        }
        var html = '';
        state.history.slice().reverse().slice(0, 10).forEach(function(s) {
          html += '<div class="pomodoro-session-item"><span>' + s.minutes + ' min focus</span><span class="pomodoro-session-time">' + s.time + '</span></div>';
        });
        historyEl.innerHTML = html;
      }
      async function saveHistory() {
        var allSessions = await ctx.api.storage.get('sessions') || [];
        var today = new Date().toISOString().slice(0, 10);
        allSessions = allSessions.filter(function(s) { return s.date === today; });
        allSessions = state.history;
        await ctx.api.storage.set('sessions', allSessions);
      }
      function tick() {
        if (state.timeLeft <= 0) {
          clearInterval(state.interval);
          state.isRunning = false;
          if (!state.isBreak) {
            var session = {
              date: new Date().toISOString().slice(0, 10),
              time: new Date().toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' }),
              minutes: Math.round(WORK_DURATION / 60)
            };
            state.history.push(session);
            state.sessionsCompleted++;
            state.todayMinutes += session.minutes;
            saveHistory();
            renderHistory();
            ctx.api.ui.showToast('Focus session complete! Take a break.', 'success');
            state.isBreak = true;
            state.timeLeft = state.sessionsCompleted % 4 === 0 ? LONG_BREAK_DURATION : BREAK_DURATION;
          } else {
            ctx.api.ui.showToast('Break over! Ready for another focus session.', 'info');
            state.isBreak = false;
            state.timeLeft = WORK_DURATION;
          }
          updateDisplay();
          return;
        }
        state.timeLeft--;
        updateDisplay();
      }
      startBtn.onclick = function() {
        if (state.isRunning) {
          clearInterval(state.interval);
          state.isRunning = false;
        } else {
          state.isRunning = true;
          state.interval = setInterval(tick, 1000);
        }
        updateDisplay();
      };
      resetBtn.onclick = function() {
        clearInterval(state.interval);
        state.isRunning = false;
        state.isBreak = false;
        state.timeLeft = WORK_DURATION;
        updateDisplay();
      };
      minimizeBtn.onclick = function() {
        state.minimized = !state.minimized;
        panel.style.display = state.minimized ? 'none' : 'flex';
        minBtn.style.display = state.minimized ? 'block' : 'none';
      };
      minBtn.onclick = function() {
        state.minimized = false;
        panel.style.display = 'flex';
        minBtn.style.display = 'none';
      };
      updateDisplay();
      renderHistory();
      self._state = state;
      var headerTitle = document.querySelector('.header h1, header h1');
      if (headerTitle) headerTitle.textContent = 'Pomodoro Desk';
      if (window.CardSpoke && window.CardSpoke.Middleware) {
        window.CardSpoke.Middleware.register({
          name: 'pomodoro-desk-save',
          priority: -100,
          operations: ['card.save'],
          handler: async function(mwCtx, next) {
            await next();
            updateDisplay();
          }
        });
      }
      ctx.logger.info('Pomodoro Desk loaded');
    },
    teardown: async function(ctx) {
      if (this._state && this._state.interval) {
        clearInterval(this._state.interval);
      }
      if (window.CardSpoke && window.CardSpoke.Middleware) {
        window.CardSpoke.Middleware.unregister('pomodoro-desk-save');
      }
      document.body.classList.remove('pomodoro-desk-active');
      if (this._panel && this._panel.parentNode) this._panel.remove();
      if (this._minBtn && this._minBtn.parentNode) this._minBtn.remove();
      var headerTitle = document.querySelector('.header h1, header h1');
      if (headerTitle && headerTitle.textContent === 'Pomodoro Desk') {
        headerTitle.textContent = 'CardSpoke';
      }
      ctx.logger.info('Pomodoro Desk disabled');
    }
  });
})();
